package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamPersonalHealthBank1 {
    private const val T = "පෞද්ගලික සෞඛ්‍යය, ඉරියව් හා ශරීර සංවර්ධනය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ලෝක සෞඛ්‍ය සංවිධානය (WHO) අනුව 'සෞඛ්‍යය' යන්නෙහි නිවැරදි නිර්වචනය කුමක්ද?", "රෝග හෝ දුබලතා නොමැතිවීම පමණක් නොව කායික, මානසික හා සමාජීය යහපැවැත්මයි", "කායික රෝගවලින් තොරවීම පමණි", "ඉහළ ශාරීරික යෝග්‍යතාවක් තිබීම පමණි", "මානසික ආතතියෙන් තොරවීම පමණි", "WHO නිර්වචනයට අනුව සෞඛ්‍යය යනු කායික, මානසික හා සමාජීය යන ත්‍රිවිධ අංශයන්හි පූර්ණ යහපැවැත්මයි."),
        q("මිනිස් සිරුරේ ප්‍රමාණය හා බරෙහි සිදුවන මැනිය හැකි ප්‍රමාණාත්මක වෙනස්වීම් හඳුන්වන්නේ කෙසේද?", "වර්ධනය", "සංවර්ධනය", "පරිණතවීම", "ප්‍රත්‍යාවර්තනය", "උස හා බර වැඩිවීම වැනි මැනිය හැකි භෞතික වෙනස්කම් වර්ධනය නම් වේ."),
        q("පුද්ගලයෙකුගේ චාලක, බුද්ධිමය, චිත්තවේගීය හා සමාජීය කුසලතාවල සිදුවන ගුණාත්මක වෙනස්වීම් හඳුන්වන්නේ කෙසේද?", "සංවර්ධනය", "වර්ධනය", "උද්ධමනය", "විභේදනය", "කුසලතා හා හැසිරීම්වල සිදුවන ක්‍රමික ගුණාත්මක ප්‍රගතිය සංවර්ධනයයි."),
        q("ළමා වියේ වර්ධනය හා සංවර්ධනය කෙරෙහි බලපාන ප්‍රධාන අභ්‍යන්තර සාධකය කුමක්ද?", "ප්‍රවේණිය සහ හෝමෝන", "ආහාර සහ පෝෂණය", "පාසල් පරිසරය", "ක්‍රීඩා උපකරණ", "දෙමව්පියන්ගෙන් උරුම වන ප්‍රවේණි සාධක හා අන්තරාසර්ග හෝමෝන අභ්‍යන්තර සාධක වේ."),
        q("ශරීරයේ දිගු අස්ථි වර්ධනය උත්තේජනය කරන පිටියුටරි ග්‍රන්ථියෙන් ශ්‍රාවය වන ප්‍රධාන හෝමෝනය කුමක්ද?", "වර්ධක හෝමෝනය (GH)", "තයිරොක්සින් හෝමෝනය", "ඉන්සියුලින් හෝමෝනය", "ඇඩ්‍රිනලින් හෝමෝනය", "පිටියුටරි ග්‍රන්ථියෙන් ශ්‍රාවය වන වර්ධක හෝමෝනය ළමා වියේ අස්ථි හා පටක වර්ධනය පාලනය කරයි."),
        q("ශරීරයේ පරිවෘත්තීය ක්‍රියා පාලනය කරමින් සාමාන්‍ය වර්ධනයට අත්‍යවශ්‍ය වන තයිරොයිඩ් ග්‍රන්ථියෙන් නිපදවන හෝමෝනය කුමක්ද?", "තයිරොක්සින්", "ග්ලුකොගන්", "ඊස්ට්‍රජන්", "ටෙස්ටොස්ටෙරෝන්", "තයිරොක්සින් හෝමෝනය මොළයේ හා ශරීරයේ ක්‍රමවත් වර්ධනයට මහෝපකාරී වේ."),
        q("දරුවෙකුගේ වර්ධනය හා සංවර්ධනය කෙරෙහි බලපාන බාහිර සාධකයකට නිදසුනක් කුමක්ද?", "සමබල පෝෂණය හා ප්‍රේමණීය පවුල් පරිසරය", "වර්ණදේහ ව්‍යුහය", "රුධිර ඝනය", "ප්‍රවේණික උස", "පෝෂණය, ආදරය, ආරක්ෂාව හා ක්‍රීඩාශීලී පරිසරය බාහිර සාධක වේ."),
        q("ශරීර ස්කන්ධ දර්ශකය (BMI) ගණනය කරනු ලබන නිවැරදි සූත්‍රය කුමක්ද?", "බර (kg) / උස (m) හි වර්ගය", "උස (m) / බර (kg)", "බර (kg) × උස (m)", "උස (cm) / බර (kg) හි වර්ගය", "BMI = බර (kg) / උස (m)² මගින් ගණනය කෙරේ."),
        q("ශරීර ස්කන්ධ දර්ශකයේ (BMI) සම්මත වර්ගීකරණය අනුව 'නිරෝගී බර' පරාසය කුමක්ද?", "18.5 සිට 24.9 දක්වා", "15.0 සිට 18.4 දක්වා", "25.0 සිට 29.9 දක්වා", "30.0 හෝ ඊට වැඩි", "BMI අගය 18.5 - 24.9 අතර පැවතීම සාමාන්‍ය නිරෝගී බර ලෙස සැලකේ."),
        q("වැඩිහිටියෙකුගේ BMI අගය 18.5 ට වඩා අඩු මට්ටමක පැවතීමෙන් පෙන්නුම් කරන තත්ත්වය කුමක්ද?", "අඩු බර තත්ත්වය", "නිරෝගී බර", "වැඩි බර", "අධි ස්ථූලතාව", "18.5 ට අඩු අගයක් ලැබීම මන්දපෝෂණය හෝ අඩු බර තත්ත්වයකි."),
        q("පුද්ගලයෙකුගේ BMI අගය 25.0 සිට 29.9 දක්වා අගයක් ගැනීමෙන් හැඟවෙන්නේ කුමක්ද?", "වැඩි බර තත්ත්වය", "අඩු බර තත්ත්වය", "නිරෝගී බර", "දරුණු මන්දපෝෂණය", "25.0 - 29.9 පරාසය වැඩි බර (Overweight) ලෙස වර්ග කෙරේ."),
        q("ශරීර ස්කන්ධ දර්ශකයේ (BMI) අගය 30.0 හෝ ඊට වැඩි වූ විට හඳුන්වන තත්ත්වය කුමක්ද?", "ස්ථූලතාව (Obesity)", "නිරෝගී බර", "අඩු බර", "ක්‍රීඩාශීලී බර", "BMI 30.0 ට වැඩි වීම ස්ථූලතාව වන අතර එය හෘද රෝග හා දියවැඩියා අවදානම ඉහළ නංවයි."),
        q("ශරීරයේ උදරීය මේදය තැන්පත්වීම හා හෘද රෝග අවදානම තක්සේරු කිරීමට යොදාගන්නා මානවමිතික මිනුම කුමක්ද?", "ඉණ සහ උකුල වටප්‍රමාණ අනුපාතය (WHR)", "හිස වටප්‍රමාණය", "පපු ප්‍රමාණය", "බලහත්කාර ශ්වසන ධාරිතාව", "Waist-to-Hip Ratio මගින් උදරයේ මේද තැන්පත් වීමේ අවදානම ගණනය කරයි."),
        q("පිරිමි පුද්ගලයෙකුගේ ඉණ-උකුල අනුපාතය (WHR) කුමන අගය ඉක්මවූ විට හෘද රෝග අවදානම ඉහළ යයිද?", "0.90 ට වැඩි වූ විට", "0.70 ට වැඩි වූ විට", "0.50 ට වැඩි වූ විට", "0.40 ට වැඩි වූ විට", "පිරිමින්ගේ WHR අගය 0.90 ඉක්මවීම හෘද වාහිනී රෝග අවදානම් සාධකයකි."),
        q("කාන්තාවකගේ ඉණ-උකුල අනුපාතය (WHR) කුමන අගය ඉක්මවූ විට පරිවෘත්තීය රෝග අවදානම ඉහළ යයිද?", "0.85 ට වැඩි වූ විට", "0.65 ට වැඩි වූ විට", "0.50 ට වැඩි වූ විට", "0.35 ට වැඩි වූ විට", "කාන්තාවන්ගේ WHR අගය 0.85 ට වඩා වැඩි වීම සෞඛ්‍ය අවදානම් ලක්ෂණයකි."),
        q("අවම ශක්තියක් වැය කරමින් ශරීරයේ සමබරතාව හා අස්ථි-පේශි ක්‍රියාකාරිත්වය සුරැකෙන ඉරියව්ව කුමක්ද?", "නිවැරදි කායික ඉරියව්ව", "අක්‍රමවත් ඉරියව්ව", "අලස ඉරියව්ව", "ආතති ඉරියව්ව", "නිවැරදි ඉරියව්වක් මගින් සිරුරේ බර ඇටසැකිල්ල පුරා සමබරව බෙදී යයි."),
        q("කොඳු ඇට පෙළේ උරස් කලාපය පිටුපසට අධික ලෙස නැමී වටකුරු උරහිස් ඇතිවීම හඳුන්වන ඉරියව් ආබාධය කුමක්ද?", "කයිෆෝසිස් (කුද ගැසීම)", "ලෝඩෝසිස්", "ස්කොලියෝසිස්", "පැතලි පාදය", "Kyphosis තත්ත්වයේදී පිටුපස කුදයක් මෙන් උරස් කශේරුකා පිටතට නෙරා යයි."),
        q("කොඳු ඇට පෙළේ කටී කලාපය (තුනටිය) ඉදිරියට නෙරා ගොස් උදරය ඉදිරියට නෙරා ඒම හඳුන්වන ඉරියව් දෝෂය කුමක්ද?", "ලෝඩෝසිස් (Lordosis)", "කයිෆෝසිස්", "ස්කොලියෝසිස්", "දුනු පාදය", "Lordosis යනු කටී කශේරුකා ඉදිරියට අධික ලෙස නැමී යාමයි."),
        q("කොඳු ඇට පෙළ පැත්තකට ('S' හෝ 'C' අකුරක හැඩයට) ඇදවීම නිසා උරහිස් අසමමිතික වන ඉරියව් ආබාධය කුමක්ද?", "ස්කොලියෝසිස් (Scoliosis)", "කයිෆෝසිස්", "ලෝඩෝසිස්", "දණහිස් ගැටීම", "Scoliosis තත්ත්වයේදී කොන්දේ කශේරුකා පර්ශ්විකව ඇදවීම සිදුවේ."),
        q("පාදයේ යටිපතුලේ සාමාන්‍යයෙන් පිහිටන චාපය (Arch) නොපිහිටා මුළු පතුලම පොළොවෙහි ස්පර්ශ වන ආබාධය කුමක්ද?", "පැතලි පාදය (Flat Foot)", "දුනු පාදය", "දණහිස් ගැටීම", "කයිෆෝසිස්", "පැතලි පාදය සහිත අයට දීර්ඝ වේලාවක් ඇවිදීමේදී හෝ ධාවනයේදී පාදවල වේදනාවක් හටගනී."),
        q("කෙළින් සිටගෙන සිටින විට දණහිස් දෙක එකිනෙක ගැටුණද වළලුකර දෙක ඈත්ව පිහිටන පාද ආබාධය කුමක්ද?", "දණහිස් ගැටීම (Knock-knees)", "දුනු පාදය", "පැතලි පාදය", "ලෝඩෝසිස්", "Genu valgum හෙවත් Knock-knees තත්ත්වයේදී දණහිස් එකිනෙක ගැටේ."),
        q("කෙළින් සිටගෙන සිටින විට වළලුකර දෙක එකට තැබූ විට දණහිස් දෙක එකිනෙකින් ඈත්ව වක්‍රව පිහිටන තත්ත්වය කුමක්ද?", "දුනු පාද (Bowlegs)", "දණහිස් ගැටීම", "පැතලි පාදය", "ස්කොලියෝසිස්", "Genu varum හෙවත් Bowlegs තත්ත්වයේදී පාද දුන්නක ආකාරයට වක්‍ර වේ."),
        q("පාසල් සිසුන් අතර ඉරියව් ආබාධ බහුලව ඇතිවීමට බලපාන ප්‍රධාන සාධකයක් වන්නේ කුමක්ද?", "බරින් වැඩි පොත් බෑග් එක් උරහිසක පමණක් එල්ලාගෙන යාම", "දිනපතා ව්‍යායාමවල යෙදීම", "උසට සරිලන මේස පුටු භාවිතය", "සමබල ආහාර වේලක් ගැනීම", "එක් උරහිසකට පමණක් අධික බර දැරීමෙන් ස්කොලියෝසිස් හා මාංශපේශී විෂමතා ඇතිවේ."),
        q("බිම ඇති බර වස්තුවක් එසවීමේදී කොන්ද ආබාධවලින් ආරක්ෂා කර ගැනීමට අනුගමනය කළ යුතු නිවැරදි ඉරියව්ව කුමක්ද?", "දණහිස් නවා කොන්ද කෙළින් තබාගෙන බර සිරුරට සමීපව තබා එසවීම", "දණහිස් නොනවා කොන්ද පමණක් පහත් කර එසවීම", "බර සිරුරෙන් ඈත් කර තබා එසවීම", "ශරීරය පැත්තකට කරකවමින් එකවර එසවීම", "බර එසවීමේදී කාර්යය කළ යුත්තේ කලවා හා පාදවල ප්‍රධාන පේශිවලින් මිස කොඳු ඇට පෙළෙන් නොවේ."),
        q("පොතක් කියවීමේදී හෝ පරිගණකයක් භාවිත කිරීමේදී හිස ඉදිරියට නමාගෙන සිටීමෙන් ඇතිවන මාංශපේශී ආතතිය කුමක්ද?", "Forward Head Posture (Text Neck)", "පැතලි පාදය", "දුනු පාදය", "Knock-knees", "ජංගම දුරකථන හා පරිගණක දෙස පහත් වී බැලීමෙන් බෙල්ලේ පේශිවලට අධික පීඩනයක් ඇතිවේ."),
        q("පුද්ගලයෙකු වාඩි වී සිටින විට කොඳු ඇට පෙළට ලැබෙන ආධාරකය සම්බන්ධයෙන් නිවැරදි පිළිවෙත කුමක්ද?", "යටි කොන්ද පුටු ඇන්දට හේත්තු වී පාද දෙකම බිම සමතලාව තැබීම", "පුටුවේ ඉදිරිපස දාරයේ පමණක් වාඩිවීම", "එක් පාදයක් උඩ අනෙක් පාදය නිතර තබාගෙන සිටීම", "ඇලවී වාඩිවීම", "නිවැරදි වාඩිවීමේ ඉරියව්ව මගින් කශේරුකාවලට සිදුවන අනවශ්‍ය පීඩනය වළකී."),
        q("නින්දේදී කොඳු ඇට පෙළෙහි ස්වාභාවික වක්‍රතාව ආරක්ෂා කර ගැනීම සඳහා සුදුසු නිදන ඉරියව්ව කුමක්ද?", "කොඳු ඇට පෙළ සෘජුව තබා පැත්තකට නිදා දණහිස් මඳක් නැවීම", "අධික උස කොට්ට කිහිපයක් භාවිත කිරීම", "උදරය මත පමණක් දිගා වී නිදාගැනීම", "ඉතා ගිලෙන මෙට්ට භාවිතය", "සුදුසු උස කොට්ටයක් සහිත මධ්‍යම ප්‍රමාණයේ තද මෙට්ටයක නිදාගැනීම සෞඛ්‍යාරක්ෂිතය."),
        q("දත්වල මතුපිට බැඳෙන බැක්ටීරියා, ආහාර කොටස් හා කෙළ එක්වීමෙන් සෑදෙන තුනී ආලේපනය කුමක්ද?", "දන්ත ඵලකය (Dental Plaque)", "දන්ත මැලියම්", "දන්ත සිමෙන්ති", "දන්ත ඇනමලය", "දන්ත ඵලකය නිසි ලෙස පිරිසිදු නොකළහොත් එය දෘඪ වී දන්ත අශ්මරි (Tartar) බවට පත්වේ."),
        q("මුඛයේ ඇති බැක්ටීරියා මගින් ආහාරවල අඩංගු සීනි පැසවීමේදී නිපදවන අම්ල මගින් දත් දිරායාමේ ක්‍රියාවලිය කුමක්ද?", "දන්ත ක්ෂය වීම (Dental Caries)", "කයිෆෝසිස්", "විදුරුමස් දියවීම", "බෙරිබෙරි", "බැක්ටීරියා නිපදවන අම්ල මගින් දතෙහි එනමලය දියවීමෙන් දන්ත කුහර ඇතිවේ."),
        q("දත් දිරායාම වළක්වා ගැනීමට සහ දත්වල එනමලය ශක්තිමත් කිරීමට පානීය ජලයට හා දන්තාලේපනවලට එක්කරන ඛනිජය කුමක්ද?", "ෆ්ලෝරයිඩ්", "අයඩීන්", "යකඩ", "සෝඩියම්", "ෆ්ලෝරයිඩ් මගින් දත් කුහර ඇතිවීම වළක්වා එනමලයේ ඛනිජකරණය ශක්තිමත් කරයි."),
        q("විදුරුමස් ඉදිමීම, රතු පැහැවීම හා දත් මදින විට ලේ ගැලීම ඇතිවන මූලික විදුරුමස් රෝගය කුමක්ද?", "ජින්ජිවයිටිස් (Gingivitis)", "ස්කර්වි", "පැරොටිටිස්", "ස්ටොමැටයිටිස්", "ජින්ජිවයිටිස් යනු නිසි මුඛ සනීපාරක්ෂාව නොමැතිකම නිසා විදුරුමස් ආසාදනය වීමයි."),
        q("දන්ත සෞඛ්‍යය නිසි පරිදි පවත්වා ගැනීම සඳහා දිනකට අවම වශයෙන් දත් මැදිය යුතු වාර ගණන කීයද?", "උදෑසන ආහාරයෙන් පසු සහ රාත්‍රී නින්දට පෙර දෙවරක්", "උදෑසන අවදි වූ වහාම එක් වරක් පමණි", "සතියකට තුන් වරක් පමණි", "ආහාර ගන්නා සෑම අවස්ථාවකම දස වරක්", "දිනකට දෙවරක් විනාඩි 2ක් පමණ නිවැරදි ක්‍රමයට දත් මැදීම නිර්දේශ කෙරේ."),
        q("දත් අතර රැඳෙන ආහාර කැබලි ඉවත් කිරීම සඳහා දන්ත වෛද්‍යවරුන් නිර්දේශ කරන වඩාත් ආරක්ෂිත ක්‍රමය කුමක්ද?", "දන්ත නූල් (Dental Floss) භාවිතය", "ලී කූරු භාවිතය", "ලෝහ කටු භාවිතය", "කොණ්ඩ කටු භාවිතය", "දන්ත නූල් මගින් විදුරුමසට හානි නොවී දත් අතර රැඳි ඵලකය ඉවත් කරයි."),
        q("සමේ බාහිර ස්ථරයෙහි සූර්යාලෝකයේ ඇති පාරජම්බුල (UV-B) කිරණ ගැටීමෙන් සිරුර තුළ නිපදවෙන අත්‍යවශ්‍ය විටමිනය කුමක්ද?", "විටමින් D", "විටමින් A", "විටමින් C", "විටමින් K", "උදෑසන මෘදු හිරු එළිය මගින් සමේ කොලෙස්ටරෝල් විටමින් D බවට පරිවර්තනය වේ."),
        q("නිතර දහඩිය රැඳෙන කිහිලි, ඉකිලි වැනි ස්ථානවල දිලීර ආසාදනය වීම නිසා සුදු හෝ දුඹුරු ලප ඇතිවන සමේ රෝගය කුමක්ද?", "අළුහම් (Tinea versicolor)", "කුෂ්ඨ", "සොරයිසිස්", "හර්පීස්", "Pityriasis versicolor හෙවත් අළුහම් තත්ත්වය පුද්ගලික අපිරිසිදුකම හා දහඩිය නිසා හටගනී."),
        q("සැකෝප්ටීස් ස්කැබියෙයි (Sarcoptes scabiei) නැමැති කුඩා පරපෝෂිත මයිටාවා මගින් ඇඟිලි කරු අතර අධික කැසීමක් ඇතිකරන බෝවන චර්ම රෝගය කුමක්ද?", "හොරි (Scabies)", "අළුහම්", "දද", "පීරංගි", "හොරි රෝගය ආසාදිත ඇඳුම් හා ඇඳ ඇතිරිලි බෙදාගැනීමෙන් කඩිනමින් බෝවේ."),
        q("සමේ සෞඛ්‍යය හා පෞද්ගලික සනීපාරක්ෂාව රැකගැනීමට දිනපතා ස්නානය කිරීමෙන් ලැබෙන ප්‍රධාන ප්‍රයෝජනය කුමක්ද?", "සමේ මළ සෛල, දහඩිය, දූවිලි හා බැක්ටීරියා ඉවත් වීම", "ශරීරයේ රුධිරය සම්පූර්ණයෙන් අඩුවීම", "සම වියළී ඉරිතලා යාම", "අස්ථි දුර්වල වීම", "දිනපතා පිරිසිදු ජලයෙන් ස්නානය කිරීමෙන් සමේ රෝම කූප විවෘත වී ආසාදන වළකී."),
        q("හිසකෙස් හා හිස්කබල පිරිසිදුව නොතැබීම නිසා හිස්කබලේ සමේ මළ සෛල කොතු ලෙස ගැලවී යාමේ තත්ත්වය කුමක්ද?", "හිස්හොරි (Dandruff)", "අළුහම්", "ඇලෝපීසියා", "චර්මදාහය", "දිලීර ක්‍රියාකාරිත්වය හා අධික තෙල් සහිත හිස්කබල නිසා හිස්හොරි ඇතිවේ."),
        q("ඇස්වල නිරෝගීභාවය සඳහා ඩිජිටල් තිර (පරිගණක, දුරකථන) භාවිතයේදී අනුගමනය කළ යුතු '20-20-20' රීතිය යනු කුමක්ද?", "සෑම මිනිත්තු 20 කට වරක් තත්පර 20 ක් අඩි 20 ක් දුර බැලීම", "මිනිත්තු 20 ක් නිදාගැනීම", "වීදුරු 20 ක් පැළඳීම", "පැය 20 ක් නොනවත්වා වැඩ කිරීම", "මෙම ක්‍රමයෙන් ඇස්වල සිලියරි පේශිවලට සිදුවන විඩාව හා ආතතිය සමනය වේ."),
        q("අක්ෂි සෞඛ්‍යය ආරක්ෂා කර ගැනීම සඳහා අත්‍යවශ්‍ය වන විටමින් වර්ගය කුමක්ද?", "විටමින් A", "විටමින් D", "විටමින් C", "විටමින් K", "විටමින් A ඌනතාව නිසා රාත්‍රී අන්ධතාවය හා වියළි අක්ෂි තත්ත්වය (Xerophthalmia) ඇතිවේ."),
        q("ශ්‍රවණ ඉන්ද්‍රිය වන කන් පිරිසිදු කිරීමේදී තියුණු හෝ දැඩි උපකරණ (උදා: කොණ්ඩ කටු, ඉරටු) නොදැමිය යුත්තේ ඇයි?", "කන් බෙරය (Tympanic membrane) සිදුරු වීමේ අවදානම ඇති බැවිනි", "කනෙහි ඇටසැකිල්ලක් නොමැති නිසා", "කන විශාල වන නිසා", "ශ්‍රවණ ස්නායුව ගැලවී යන නිසා", "තියුණු ද්‍රව්‍ය දැමීමෙන් කන් බෙරයට හානි වී ස්ථිර බිහිරිභාවය ඇතිවිය හැක."),
        q("පාසල් ළමුන්ගේ සෞඛ්‍ය තත්ත්වය, වර්ධනය හා ප්‍රතිශක්තිකරණය වාර්ෂිකව සටහන් කර පරීක්ෂා කරන නිල ලේඛනය කුමක්ද?", "පාසල් සෞඛ්‍ය වෛද්‍ය පරීක්ෂණ වාර්තාව (SHMR)", "පැමිණීමේ ලේඛනය", "වාර විභාග ලකුණු පොත", "ක්‍රීඩා සහතිකය", "පාසල් වෛද්‍ය පරීක්ෂණයේදී (SMI) උස, බර, පෙනීම, දත් හා ඉරියව් පරීක්ෂා කර සටහන් කරයි."),
        q("නව යොවුන් වියේ පසුවන දරුවෙකුට දිනකට අවශ්‍ය අවම ප්‍රශස්ථ නින්ද කොපමණද?", "පැය 8 සිට 10 දක්වා", "පැය 4 සිට 5 දක්වා", "පැය 12 සිට 14 දක්වා", "පැය 2 සිට 3 දක්වා", "නින්දේදී මොළයේ සෛල විවේක ගන්නා අතර වර්ධක හෝමෝන ශ්‍රාවය වීම උපරිම වේ."),
        q("ප්‍රමාණවත් නින්දක් නොලැබීම නිසා සිසුවෙකු තුළ ඇතිවිය හැකි සෘණාත්මක ප්‍රතිඵලයක් නොවන්නේ කුමක්ද?", "ඉහළ මතක ශක්තිය හා ඉහළ ප්‍රබෝධය", "දිවා කාලයේ නිදිමත ගතිය", "අවධානය යොමු කිරීමේ අපහසුව", "ප්‍රතිශක්තිකරණය දුර්වල වීම", "ප්‍රමාණවත් නින්ද නොලැබීමෙන් මතකය හා ප්‍රබෝධය හීන වේ."),
        q("උදාසීන ජීවන රටාවක් (Sedentary Lifestyle) ගත කිරීම නිසා ඇතිවිය හැකි දිගුකාලීන සෞඛ්‍ය ගැටලුවක් කුමක්ද?", "තරබාරුකම සහ බෝ නොවන රෝග අවදානම", "අස්ථි ඝනත්වය අධික ලෙස වැඩිවීම", "හෘද ස්පන්දන වේගය සාමාන්‍ය මට්ටමට වඩා අඩුවීම", "මාංශපේශී අනවශ්‍ය ලෙස විශාල වීම", "ශාරීරික අක්‍රියතාව අධික බර, දියවැඩියාව හා අධි රුධිර පීඩනයට ප්‍රධාන හේතුවකි."),
        q("සෞඛ්‍ය සම්පන්න ජීවන රටාවකට හුරුවීම සඳහා පාසල් සිසුවෙකු දිනපතා ගත කළ යුතු අවම මධ්‍යස්ථ-තීව්‍ර ශාරීරික ව්‍යායාම කාලය කුමක්ද?", "අවම වශයෙන් විනාඩි 60 ක්", "විනාඩි 5 ක් පමණි", "පැය 4 ක්", "සතියකට වරක් විනාඩි 10 ක්", "ළමුන් සහ යෞවනයන් දිනපතා අවම වශයෙන් විනාඩි 60 ක ක්‍රියාශීලී ව්‍යායාමවල යෙදිය යුතුය."),
        q("පාදවල නියපොතු කැපීමේදී අනුගමනය කළ යුතු නිවැරදි සනීපාරක්ෂක ක්‍රමය කුමක්ද?", "නියපොත්තේ දාර වක්‍ර නොකර සෘජුව හරහට කැපීම", "දත්වලින් සපා ඉවත් කිරීම", "නිය කෙළවර සම තුළට ගැඹුරට හාරා කැපීම", "මාස ගණනාවක් නොකපා තැබීම", "යටිපතුලේ නියපොතු සෘජුව කැපීමෙන් නියපොතු මස් තුළට කිඳාබැසීම (Ingrown toenails) වළකී."),
        q("අත් සේදීමේ නිවැරදි පියවර අනුගමනය කරමින් සබන් යොදා අවම වශයෙන් අත් සේදිය යුතු කාලය කොපමණද?", "තත්පර 20 ක කාලයක්", "තත්පර 2 ක කාලයක්", "මිනිත්තු 15 ක කාලයක්", "තත්පර 5 ක කාලයක්", "අත්ල, පිටිඅල්ල, ඇඟිලි කරු හා නියපොතු අවම තත්පර 20ක් සබන් යොදා පිරිසිදු කළ යුතුය."),
        q("ආහාර ගැනීමට පෙර සහ වැසිකිළි භාවිතයෙන් පසු අත් සේදීම මගින් වළක්වා ගත හැකි ප්‍රධාන රෝග කාණ්ඩය කුමක්ද?", "ආන්ත්‍රික ආසාදන සහ පාචන රෝග", "ඩෙංගු උණ", "මැලේරියාව", "ඇදුම රෝගය", "අපිරිසිදු අත් මගින් බැක්ටීරියා හා වෛරස් මුඛයට ඇතුළු වීමෙන් උදරාබාධ හටගනී."),
        q("ලෝක සෞඛ්‍ය සංවිධානය (WHO) විසින් හඳුන්වා දී ඇති 'සෞඛ්‍ය ප්‍රවර්ධන පාසලක' (Health Promoting School) ප්‍රධාන අංග ගණන කීයද?", "හයකි (6)", "දෙකකි (2)", "දහයකි (10)", "විසිපහකි (25)", "පාසල් සෞඛ්‍ය ප්‍රතිපත්ති, භෞතික පරිසරය, සමාජ පරිසරය, ප්‍රජා සබඳතා, කුසලතා හා සෞඛ්‍ය සේවා එම අංග 6 වේ."),
        q("සෞඛ්‍ය ප්‍රවර්ධන පාසලක 'හිතකර භෞතික පරිසරය' යන්නට අයත් වන්නේ කුමක්ද?", "ආරක්ෂිත ගොඩනැගිලි, ක්‍රීඩා පිටි, පිරිසිදු පානීය ජලය හා ප්‍රමාණවත් වැසිකිළි", "විදුහල්පති කාර්යාලය පමණක්", "අධික ශබ්දය ඇති කර්මාන්තශාලා", "අනාරක්ෂිත කාණු පද්ධති", "භෞතික පරිසරය දරුවන්ට අනතුරුවලින් තොර ආරක්ෂිත ඉගෙනුම් ඉඩකඩක් සැපයිය යුතුය."),
        q("පාසල් ළමුන්ගේ පෙනීමේ තීව්‍රතාව පරීක්ෂා කිරීම සඳහා පාසල් වෛද්‍ය පරීක්ෂණයේදී භාවිත කරන ප්‍රමිතිගත පුවරුව කුමක්ද?", "ස්නෙලන් පුවරුව (Snellen Chart)", "ඉෂිහාරා පුවරුව", "මිනුම් පටිය", "උෂ්ණත්වමානය", "අකුරු ප්‍රමාණයන්ගෙන් යුත් ස්නෙලන් පුවරුව මීටර් 6ක් දුර සිට කියවීමෙන් පෙනීම මනිනු ලැබේ."),
        q("ස්නෙලන් පුවරුවෙන් පරීක්ෂා කිරීමේදී සාමාන්‍ය නිරෝගී ඇසක දෘෂ්ටි තීව්‍රතාව සටහන් වන්නේ කුමන අනුපාතයකින්ද?", "6/6 (මීටර් 6 කදී සාමාන්‍ය අක්ෂියකට පෙනෙන දුර)", "6/60", "20/100", "1/10", "6/6 පෙනීම යනු සාමාන්‍ය නිරෝගී පුද්ගලයෙකු මීටර් 6 කදී දකින දේ එම දුරින්ම දැකීමේ හැකියාවයි."),
        q("පාසල් ළමුන්ගේ වර්ණ අන්ධතාව (Color Blindness) හඳුනාගැනීම සඳහා භාවිත කරන විශේෂ පරීක්ෂණ පුවරුව කුමක්ද?", "ඉෂිහාරා පුවරුව (Ishihara Test)", "ස්නෙලන් පුවරුව", "ග්ලූකෝමීටරය", "ස්ටෙතස්කෝපය", "වර්ණ තිත් අතර සැඟවුණු අංක හඳුනාගැනීමෙන් රතු-කොළ වර්ණ අන්ධතාව පරීක්ෂා කෙරේ."),
        q("ළමා වියේදී පානීය ජලයේ ෆ්ලෝරයිඩ් සාන්ද්‍රණය අතිශය ඉහළ මට්ටමක පැවතීම නිසා දත්වල ඇතිවන විකෘතිතාව කුමක්ද?", "දන්ත ෆ්ලෝරෝසිස් (දත් මත දුඹුරු හෝ සුදු ලප ඇතිවීම)", "ස්කර්වි", "දන්ත ක්ෂය වීම", "ජින්ජිවයිටිස්", "අධික ෆ්ලෝරයිඩ් මට්ටම එනමලයට හානි කරමින් දත් අවපැහැ ගැන්වීමට හේතු වේ."),
        q("ශරීරයේ ඉරියව්වල සෘජු බව හා සමබරතාව පරීක්ෂා කිරීම සඳහා සිරස්ව එල්ලා බලන සරල උපකරණය කුමක්ද?", "ලඹ රේඛාව (Plumb line test)", "උස මනින මාපකය", "ස්නෙලන් පුවරුව", "ඉෂිහාරා පුවරුව", "ලඹ රේඛාව කන, උරහිස, උකුල, දණහිස හා වළලුකර හරහා සිරස්ව ගමන් කරන්නේදැයි පරීක්ෂා කරයි."),
        q("පුද්ගලයෙකු බිත්තියකට හේත්තු වී සිටින විට හිස, උරහිස්, තට්ටම් හා විලුඹ බිත්තියේ ස්පර්ශ කර බැලීමෙන් පරීක්ෂා කරන්නේ කුමක්ද?", "ශරීරයේ ස්වාභාවික ඉරියව් පෙළගැස්ම (Wall Test)", "උපරිම හෘද ස්පන්දනය", "පෙනහළු ධාරිතාව", "රුධිර පීඩනය", "Wall test මගින් කොන්දේ අසාමාන්‍ය වක්‍රතා හෝ කයිෆෝසිස්/ලෝඩෝසිස් ලක්ෂණ හඳුනාගත හැක."),
        q("පුද්ගලයෙකුගේ සිරුරේ බරින් 'මේද ස්කන්ධය' සහ 'මේද රහිත පේශි හා අස්ථි ස්කන්ධය' අතර අනුපාතය හඳුන්වන්නේ කෙසේද?", "ශරීර සංයුතිය (Body Composition)", "ශරීර ස්කන්ධ දර්ශකය", "පරිවෘත්තීය අනුපාතය", "රුධිර සංසරණ අනුපාතය", "යෝග්‍යතාවයේ ප්‍රධාන සෞඛ්‍ය සංරචකයක් වන්නේ මේදය හා පේශි අතර නිවැරදි සමබරතාවයි."),
        q("පරිගණක හෝ ජංගම දුරකථන තිර දෙස දිගු වේලාවක් බලා සිටීමෙන් හටගන්නා අක්ෂි තෙහෙට්ටුව, හිසරදය හා ඇස් දැවිල්ල හඳුන්වන්නේ කෙසේද?", "පරිගණක දෘෂ්ටි සින්ඩ්‍රෝමය (Computer Vision Syndrome)", "ඇස්ටිග්මැටිසම්", "ග්ලුකෝමා", "සුද ඒම", "තිරය දෙස බැලීමේදී ඇසිපිය හෙළන වාර ගණන අඩුවීම නිසා ඇස් වියළීමට ලක්වේ."),
        q("ඇස්වල නිරෝගීභාවය සඳහා පරිගණක තිරය සහ ඇස් අතර තිබිය යුතු අවම සම්මත දුර ප්‍රමාණය කොපමණද?", "අඟල් 20 සිට 24 දක්වා (සෙන්ටිමීටර් 50-60 පමණ)", "අඟල් 2 ක් පමණ", "මීටර් 5 ක්", "අඟල් 40 ක්", "තිරය ඇසේ මට්ටමට වඩා මඳක් පහළින් අඟල් 20-24 දුරින් තබාගැනීම සෞඛ්‍යාරක්ෂිතය."),
        q("සමෙහි නිරෝගීභාවය හා ආසාදන වැළැක්වීම සඳහා භාවිත කරන පෞද්ගලික තුවා, ඇඳුම් හා පනාවන් පිළිබඳ නිවැරදි සෞඛ්‍ය පිළිවෙත කුමක්ද?", "තම පෞද්ගලික භාවිතයට පමණක් සීමා කර අන් අය සමග හවුලේ භාවිත නොකිරීම", "මුළු පවුලම එකම තුවාය භාවිත කිරීම", "මාස ගණනාවක් නොසේදීම", "තෙතමනය සහිතව අඳුරු තැනක තැබීම", "පුද්ගලික ද්‍රව්‍ය හවුලේ භාවිත කිරීමෙන් චර්ම රෝග, උකුණන් හා දිලීර ආසාදන බෝවේ."),
        q("පාදවල ඇඟිලි කරු අතර දිලීර ආසාදනය වීමෙන් සම සුදු වී කැසීම හටගන්නා 'ක්‍රීඩකයාගේ පාදය' (Athlete's foot) වැළැක්වීමට කළ යුත්තේ කුමක්ද?", "පාද සෝදා ඇඟිලි කරු හොඳින් පිසදා වියළිව තබාගැනීම හා පිරිසිදු මේස් පැළඳීම", "තෙත මේස් දින ගණනාවක් පැළඳීම", "පාවහන් නොමැතිව පොදු අපිරිසිදු තැන්වල ඇවිදීම", "පාද නොසේදීම", "Tinea pedis හෙවත් ඇත්ලීට්ස් ෆූට් තත්ත්වය තෙතමනය සහිත සංවෘත සපත්තු තුළ බහුලව වර්ධනය වේ."),
        q("දිනපතා යට ඇඳුම් මාරු කිරීම හා පිරිසිදු වියළි යට ඇඳුම් ඇඳීමෙන් වළක්වා ගත හැකි ප්‍රධාන ගැටලුව කුමක්ද?", "ප්‍රජනක හා ලිංගික ප්‍රදේශ ආශ්‍රිත දිලීර හා බැක්ටීරියා ආසාදන", "අස්ථි බිඳීම්", "දත් දිරායාම", "පෙනීම දුර්වල වීම", "දහඩිය හා තෙතමනය රැඳෙන ප්‍රදේශ පිරිසිදුව හා වියළිව තබාගැනීම ආසාදන වළක්වයි."),
        q("නින්දේදී සිරුරේ අලුත්වැඩියාව සඳහා හෝමෝන ශ්‍රාවය වීම සහ මොළයේ විවේකය තහවුරු කරන ප්‍රධාන නින්දේ අවධිය කුමක්ද?", "ගැඹුරු නින්ද (Deep Sleep / Non-REM)", "සැහැල්ලු නිදිබර ගතිය", "දිවා විවේකය", "ඇසිපිය හෙළීම", "ගැඹුරු නින්දේදී පටක ප්‍රතිසංස්කරණය වන අතර ප්‍රතිශක්තිකරණ පද්ධතිය ශක්තිමත් වේ."),
        q("මිනිස් සිරුරේ උස මැනීමේදී යොදාගන්නා සම්මත වෛද්‍ය උපකරණය හඳුන්වන්නේ කුමන නමින්ද?", "ස්ටේඩියෝමීටරය (Stadiometer)", "ස්ෆිග්මෝමනෝමීටරය", "ග්ලූකෝමීටරය", "තත්පර ඔරලෝසුව", "Stadiometer මගින් පුද්ගලයා සෘජුව සිටුවා නිවැරදි උස සෙන්ටිමීටර් හෝ මීටර්වලින් මනිනු ලැබේ."),
        q("ශරීරයේ බර මැනීමේදී නිවැරදි අගයක් ලබාගැනීම සඳහා අනුගමනය කළ යුතු පිළිවෙත කුමක්ද?", "සැහැල්ලු ඇඳුම් ඇඳ පාවහන් නොමැතිව සමතලා තරාදියක් මත සිටගැනීම", "බරැති කබා සහ සපත්තු පැළඳ සිටීම", "තරාදිය මත එක් පාදයක් පමණක් තැබීම", "විශාල බෑගයක් කර තබා සිටීම", "නිවැරදි බර ලබාගැනීමට හිස් බඩ හෝ දවසේ නියමිත වේලාවක මැනීම සුදුසුය."),
        q("මිනිස් සිරුරේ අස්ථි නිරෝගීව හා ශක්තිමත්ව පවත්වා ගැනීමට අත්‍යවශ්‍ය වන ප්‍රධාන ඛනිජය කුමක්ද?", "කැල්සියම් සහ පොස්පරස්", "යකඩ සහ තඹ", "සෝඩියම් සහ ක්ලෝරයිඩ්", "අයඩීන් සහ සින්ක්", "කැල්සියම් අස්ථි හා දත්වල ප්‍රධාන ව්‍යුහාත්මක සංරචකය වේ."),
        q("ළමා වියේදී කැල්සියම් සහ විටමින් D ඌනතාව නිසා අස්ථි මෘදු වී පාද දුනු හැඩයට වක්‍ර වන රෝගය කුමක්ද?", "රිකට්ස් (Rickets)", "ස්කර්වි", "ගලගණ්ඩය", "බෙරිබෙරි", "විටමින් D මගින් බඩවැල්වලින් කැල්සියම් අවශෝෂණය කරන අතර එහි ඌනතාවෙන් රිකට්ස් හටගනී."),
        q("වැඩිහිටි වියේදී අස්ථිවල ඛනිජ ඝනත්වය අඩුවී අස්ථි සිදුරු සහිත හා බිඳෙනසුලු වන තත්ත්වය කුමක්ද?", "ඔස්ටියෝපොරෝසිස් (Osteoporosis)", "ආතරයිටිස්", "ස්කොලියෝසිස්", "කයිෆෝසිස්", "කාන්තාවන්ගේ ආර්තවහරණයෙන් පසු ඊස්ට්‍රජන් අඩුවීම හා කැල්සියම් ඌනතාව මීට ප්‍රධාන හේතුවකි."),
        q("නිරෝගී අස්ථි වර්ධනයක් සඳහා දිනපතා අවම වශයෙන් කොපමණ වේලාවක් උදෑසන හිරු එළියට නිරාවරණය වීම ප්‍රමාණවත්ද?", "මිනිත්තු 15 සිට 20 දක්වා", "පැය 6 ක් නොකඩවා", "තත්පර 10 ක් පමණක්", "දිනකට වරක්වත් අවශ්‍ය නොවේ", "උදෑසන මෘදු හිරු එළියට මුහුණ, අත් හා පාද නිරාවරණය වීමෙන් සිරුරට අවශ්‍ය විටමින් D නිපදවේ."),
        q("ශාරීරික ඉරියව් නිවැරදිව තබාගැනීමෙන් ශරීරයේ අභ්‍යන්තර ඉන්ද්‍රියයන්ට ලැබෙන වාසිය කුමක්ද?", "පෙනහළු, හෘදය හා ආහාර ජීරණ අවයවවලට නිදහසේ ක්‍රියා කිරීමට ප්‍රමාණවත් ඉඩකඩ ලැබීම", "ඉන්ද්‍රියයන් හැකිලී යාම", "රුධිර ගමනාගමනය අවහිර වීම", "හුස්ම ගැනීමේ අපහසුව ඇතිවීම", "හොඳ ඉරියව්වක් මගින් උරස් හා උදර කුහරවල පීඩනය ලිහිල් වී ඉන්ද්‍රිය කාර්යක්ෂමතාව වැඩිවේ."),
        q("වැරදි ඉරියව් පුරුදු නිසා ශ්වසන පද්ධතියට සිදුවන අයහපත් බලපෑම කුමක්ද?", "පපු කුහරය සම්පීඩනය වීමෙන් පෙනහළු ප්‍රසාරණය වීම සීමා වී ඔක්සිජන් ලබාගැනීම අඩුවීම", "පෙනහළු ධාරිතාව අනවශ්‍ය ලෙස දෙගුණ වීම", "ශ්වාසනාලය විශාල වීම", "ශ්වසන වේගය සාමාන්‍ය වීම", "කුද ගසා වාඩිවීමෙන් පෙනහළුවලට සම්පූර්ණයෙන් ප්‍රසාරණය වීමට බාධා පැමිණේ."),
        q("පාසල් ශිෂ්‍යයෙකුගේ පෞද්ගලික සෞඛ්‍ය පුරුද්දක් ලෙස නියපොතු නිතර කොටට කපා පිරිසිදුව තබාගැනීම වැදගත් වන්නේ ඇයි?", "නිය යට අපද්‍රව්‍ය හා පණු බිත්තර රැඳී ආහාර මගින් ශරීරගත වීම වැළැක්වීමට", "නියපොතු නොවැඩී යාමට", "ඇඟිලි කුඩා වීමට", "අත්වල ශක්තිය වැඩි කිරීමට", "දිගු නියපොතු යට ක්ෂුද්‍රජීවීන් පහසුවෙන් එක්රැස් වන බැවින් ඒවා පිරිසිදුව තැබිය යුතුය."),
        q("හිසකෙස් සෞඛ්‍ය සම්පන්නව තබාගැනීම සඳහා හිස්කබල පිරිසිදු කිරීමට අමතරව වැදගත් වන පෝෂණ සාධකය කුමක්ද?", "ප්‍රෝටීන, යකඩ හා විටමින් බහුල සමබල ආහාර වේලක්", "අධික තෙල් සහිත ක්ෂණික ආහාර", "පැණිබීම පමණක් පානය කිරීම", "ආහාර නොගෙන සිටීම", "හිසකෙස් කෙරටින් නැමැති ප්‍රෝටීනයෙන් සෑදී ඇති බැවින් ප්‍රෝටීන හා යකඩ අත්‍යවශ්‍ය වේ."),
        q("අක්ෂි ආරක්ෂාව සඳහා දැඩි සූර්යාලෝකය හෝ පාරජම්බුල කිරණවලින් ඇස් ආරක්ෂා කර ගැනීමට භාවිත කළ හැකි උපාංගය කුමක්ද?", "පාරජම්බුල (UV) කිරණ අවහිර කරන අව් කණ්ණාඩි (Sunglasses)", "සාමාන්‍ය විශාලන කාච", "වර්ණ වීදුරු පමණක්", "අන්වීක්ෂ", "UV-A සහ UV-B කිරණවලින් ඇසේ සුද ඒම (Cataract) හා දෘෂ්ටි විතානයට හානිවීම වළක්වයි."),
        q("පාසල් සෞඛ්‍ය ප්‍රවර්ධන වැඩසටහන් මගින් සිසුන් තුළ ගොඩනැංවීමට අපේක්ෂා කරන මූලික කුසලතාව කුමක්ද?", "තම සෞඛ්‍යය පිළිබඳ තීරණ ගැනීමේ හැකියාව හා යහපත් සෞඛ්‍ය පුරුදු ප්‍රගුණ කිරීම", "ඖෂධ වර්ග තනිව නියම කර ගැනීම", "වෛද්‍යවරුන් නොමැතිව සැත්කම් කිරීම", "ක්‍රීඩාවලින් සම්පූර්ණයෙන්ම ඈත්වීම", "සෞඛ්‍ය දැනුම, ආකල්ප හා චර්යාත්මක කුසලතා දියුණු කිරීම මෙහි මූලික ඉලක්කයයි."),
        q("මුඛයෙන් නිතර දුර්ගන්ධය හැමීම හෙවත් 'හැලිටෝසිස්' (Halitosis) තත්ත්වයට බලපාන ප්‍රධානතම හේතුව කුමක්ද?", "දිව හා දත් මතුපිට බැක්ටීරියා හා ආහාර කොටස් රැඳී පැසවීම", "නිතර ජලය පානය කිරීම", "නිවැරදිව දත් මැදීම", "පළතුරු ආහාරයට ගැනීම", "දිව පිරිසිදු නොකිරීම හා දන්ත ඵලකය රැඳීම මුඛ දුර්ගන්ධයට ප්‍රධාන හේතුවයි."),
        q("දත් මදින සෑම අවස්ථාවකදීම දිව පිරිසිදු කිරීම (Tongue scraping / cleaning) වැදගත් වන්නේ ඇයි?", "දිව මත රැඳෙන බැක්ටීරියා හා සෛල කොටස් ඉවත් කර මුඛ දුර්ගන්ධය වැළැක්වීමට", "රස අංකුර සම්පූර්ණයෙන් ඉවත් කිරීමට", "දත් සුදු කිරීමට", "කෙළ නිෂ්පාදනය නැවැත්වීමට", "දිවේ මතුපිට විශාල බැක්ටීරියා ප්‍රමාණයක් රැඳෙන බැවින් එය පිරිසිදු කිරීම අත්‍යවශ්‍යය."),
        q("පෞද්ගලික සෞඛ්‍යය රැකගැනීමේදී 'සෞඛ්‍ය සම්පන්න පුරුදු' කුඩා කල සිටම ඇති කිරීම වැදගත් වන්නේ ඇයි?", "එම පුරුදු ජීවිත කාලය පුරාම ස්ථිර චර්යාවන් බවට පත්වී නිරෝගීභාවය සුරකින බැවිනි", "විභාග සඳහා පමණක් ලකුණු ගැනීමට", "වෛද්‍යවරුන් බිය කිරීමට", "පාසල් නිල ඇඳුම් පිරිසිදුව තබාගැනීමට පමණක්", "කුඩා කල හුරු වන සනීපාරක්ෂක හා ආහාර පුරුදු වැඩිහිටි වියේ බෝ නොවන රෝග වළක්වයි."),
        q("පාසල් සෞඛ්‍ය ප්‍රවර්ධන කමිටුවේ (School Health Promotion Committee) සංයුතියට අයත් සාමාජිකයන් කවුද?", "විදුහල්පති, ගුරුවරුන්, දෙමව්පියන්, ශිෂ්‍ය නායකයන් හා ප්‍රදේශයේ සෞඛ්‍ය වෛද්‍ය නිලධාරී (MOH)", "දේශපාලන පක්ෂ නියෝජිතයන් පමණි", "පොලිස් නිලධාරීන් පමණි", "ව්‍යාපාරිකයන් පමණි", "පාසල හා ප්‍රජාව එක්ව පාසල් දරුවන්ගේ සෞඛ්‍යය නංවාලීමට මෙම කමිටුව ක්‍රියා කරයි."),
        q("ශිෂ්‍යයෙකුගේ මානසික සුවතාව හා ප්‍රබෝධය රඳවා ගැනීමට දිනපතා ප්‍රමාණවත් විවේකයක් හා ක්‍රීඩාවක් වැදගත් වන්නේ ඇයි?", "ආතතිය දුරුවී එන්ඩොෆින් හෝමෝන ශ්‍රාවය වීමෙන් මනස ප්‍රබෝධමත් වන බැවිනි", "කාලය අපතේ යැවීමට", "ශරීරයේ බර අධික ලෙස අඩු කිරීමට", "පාඩම් කිරීම සම්පූර්ණයෙන් නැවැත්වීමට", "ශාරීරික ක්‍රියාකාරකම් මගින් සතුට හා මානසික සැහැල්ලුව ඇති කරන හෝමෝන නිපදවේ."),
        q("නිරෝගී ඉරියව්වක් පවත්වා ගැනීම සඳහා උදරයේ මාංශපේශී (Abdominal muscles) ශක්තිමත් කිරීම වැදගත් වන්නේ ඇයි?", "එමගින් තුනටිය ප්‍රදේශය ඉදිරියට නැමීම වළක්වා කොඳු ඇට පෙළට ආධාරකයක් වන බැවිනි", "ආහාර රුචිය සම්පූර්ණයෙන්ම නැති කිරීමට", "අක්මාව විශාල කිරීමට", "හුස්ම ගැනීම නැවැත්වීමට", "උදර පේශි ශක්තිමත් වීම ලෝඩෝසිස් ඉරියව් ආබාධය වැළැක්වීමට මූලික වේ."),
        q("ඉරියව් දෝෂ කලින් හඳුනාගෙන නිවැරදි කර නොගතහොත් වැඩිහිටි වියේදී ඇතිවිය හැකි සංකූලතාව කුමක්ද?", "නිදන්ගත කොන්දේ හා සන්ධිවල වේදනාව සහ අස්ථි ගෙවී යාම", "අස්ථි දිගු වීම", "දත් වැටීම", "අක්ෂි ආබාධ", "යෞවන වියේ නිවැරදි නොකරන ලද ඉරියව් දෝෂ වැඩිහිටි වියේදී ස්ථිර ආබාධ බවට පත්වේ."),
        q("පාසල් බෑගයක් රැගෙන යාමේදී කොඳු ඇට පෙළට අවම හානියක් වන වඩාත්ම සුදුසු ක්‍රමය කුමක්ද?", "පටි දෙකම උරහිස් දෙකට දමා බෑගය පිටුපස මැදට තද වන සේ සකසා ගැනීම", "එක් උරහිසක පමණක් එල්ලාගෙන යාම", "අතින් පමණක් ඔසවාගෙන යාම", "බෑගය ඉතා පහළට එල්ලෙන සේ තැබීම", "උරහිස් දෙකටම සමබරව බර බෙදී යාමෙන් කොන්ද පැත්තකට ඇදවීම වළකී."),
        q("පාසලේදී හෝ නිවසේදී අධ්‍යයන කටයුතු කරන විට ආලෝකය ලැබිය යුතු නිවැරදි දිශාව කුමක්ද?", "දකුණත්කරුවෙකුට වම් පසින් හා ඉදිරියෙන් ආලෝකය පතිත වීම", "පිටුපසින් පමණක් අඳුරු ආලෝකය ලැබීම", "සෘජුවම ඇස්වලට එල්ල වන අධික ආලෝකය", "පොත මතට සෙවණැල්ල වැටෙන සේ දකුණු පසින්", "ලියන අතේ සෙවණැල්ල පොත මත නොවැටෙන සේ විරුද්ධ පැත්තෙන් ආලෝකය ලැබිය යුතුය."),
        q("සිරුරේ බර 75 kg සහ උස 1.7 m වූ පුද්ගලයෙකුගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "25.95 kg/m² (වැඩි බර)", "18.0 kg/m² (අඩු බර)", "21.5 kg/m² (නිරෝගී)", "32.0 kg/m² (ස්ථූල)", "BMI = 75 / (1.7 × 1.7) = 75 / 2.89 = 25.95 kg/m² (වැඩි බර)."),
        q("සිරුරේ බර 50 kg සහ උස 1.6 m වූ දැරියකගේ BMI අගය නිවැරදිව ගණනය කළ විට ලැබෙන්නේ කුමක්ද?", "19.53 kg/m² (නිරෝගී බර)", "26.0 kg/m² (වැඩි බර)", "15.0 kg/m² (අඩු බර)", "31.5 kg/m² (ස්ථූල)", "BMI = 50 / (1.6 × 1.6) = 50 / 2.56 = 19.53 kg/m² (නිරෝගී බර)."),
        q("නිරෝගී දිවියක් උදෙසා 'සෞඛ්‍ය සාක්ෂරතාව' (Health Literacy) පුද්ගලයෙකු තුළ තිබීම වැදගත් වන්නේ ඇයි?", "නිවැරදි සෞඛ්‍ය තොරතුරු තේරුම් ගෙන තම ජීවිතය පිළිබඳ ඥානාන්විත තීරණ ගැනීමට", "ව්‍යාජ ප්‍රචාරවලට රැවටීමට", "ඖෂධ අධික මාත්‍රාවලින් ගැනීමට", "රෝහල්වලට යාම නැවැත්වීමට", "සෞඛ්‍ය සාක්ෂරතාව ඇති තැනැත්තා සෞඛ්‍ය සම්පන්න ජීවන තේරීම් නිවැරදිව සිදු කරයි."),
        q("දන්ත සනීපාරක්ෂාවේදී 'දන්ත බුරුසුවක්' සාමාන්‍යයෙන් කොපමණ කලකට වරක් අලුතින් මාරු කළ යුතුද?", "මාස 3 කට වරක් හෝ කෙඳි විසිරී ගිය වහාම", "වසර 5 කට වරක්", "එකම බුරුසුව ජීවිත කාලය පුරාම", "දිනපතා අලුත් බුරුසුවක්", "කෙඳි ගෙවී විසිරී ගිය බුරුසුවකින් දත් මතුපිට හා විදුරුමස් පිරිසිදු කිරීම නිසි ලෙස සිදු නොවේ."),
        q("සම මතුපිට පිහිටි දහඩිය ග්‍රන්ථිවලින් නිකුත් වන දහඩිය දුර්ගන්ධයක් බවට පත්වීමට මූලික හේතුව කුමක්ද?", "දහඩියෙහි අඩංගු කාබනික ද්‍රව්‍ය සම මතුපිට බැක්ටීරියා මගින් වියෝජනය වීම", "දහඩියෙහි කිසිදු ද්‍රව්‍යයක් නොමැති වීම", "සම වියළී යාම", "රුධිරය පිටතට පැමිණීම", "නැවුම් දහඩිය ගන්ධ රහිත වන නමුත් බැක්ටීරියා ක්‍රියාකාරිත්වය නිසා ශරීර දුර්ගන්ධය ඇතිවේ."),
        q("පාසල් ශිෂ්‍යයෙකුගේ නිරෝගී වර්ධනය සඳහා දිනපතා ආහාර වේලට එක්කර ගත යුතු 'තන්තු බහුල' ආහාර මොනවාද?", "කොළ පැහැති පලා වර්ග, එළවළු, පළතුරු හා නිවුඩු ධාන්‍ය", "සීනි සහ පැණි රස කෑම", "ක්ෂණික නූඩ්ල්ස් සහ සොසේජස්", "ක්ෂණික ගැඹුරු තෙලේ බදින ලද කෑම", "ආහාරමය තන්තු මගින් මලබද්ධය වළක්වා ආහාර මාර්ගයේ නිරෝගීභාවය ආරක්ෂා කරයි."),
        q("ශාරීරික ක්‍රියාකාරකම්වල යෙදෙන විට නිවැරදි 'ක්‍රීඩා ඇඳුම්' තෝරාගැනීමේදී මූලිකවම සැලකිලිමත් විය යුත්තේ කුමක් ගැනද?", "දහඩිය උරාගන්නා, වාතාශ්‍රය ලැබෙන හා චලනයන්ට බාධා නොවන ලිහිල් ඇඳුම් වීම", "ඉතා තද සහ ඝනකම් ඇඳුම් වීම", "වාතය නොකෙරෙන ප්ලාස්ටික් ඇඳුම්", "අධික බරැති ලොම් ඇඳුම්", "ක්‍රීඩා ඇඳුම් ශරීරයේ තාපය පිටවීමට හා නිදහස් චලනයන්ට ඉඩ සැලසිය යුතුය."),
        q("ශිෂ්‍යයෙකු තම පෞද්ගලික සෞඛ්‍යය නංවාලීම සඳහා දින චර්යාවකට (Daily Routine) අනුව කටයුතු කිරීමෙන් ලැබෙන ප්‍රතිලාභය කුමක්ද?", "කාල කළමනාකරණය, නිසි පෝෂණය, ප්‍රමාණවත් නින්ද හා මනසේ සන්සුන් බව තහවුරු වීම", "අධික වෙහෙස හා මානසික අවුල් සහගත බව", "ශාරීරික අලස බව", "මිතුරන් සමග නිතර ගැටුම් ඇතිවීම", "විධිමත් දින චර්යාව ජීවිතයේ විනය හා දිගුකාලීන නිරෝගී පැවැත්මට මග පාදයි."),
        q("පාසල් සෞඛ්‍ය ප්‍රවර්ධන පරිසරයක 'මානසික-සමාජීය පරිසරය' (Psychosocial Environment) යහපත්ව පැවතීම යන්නෙන් අදහස් වන්නේ කුමක්ද?", "හිංසනයෙන් තොර, ගුරුවරුන් හා සිසුන් අතර සුහදශීලී, සාධාරණ හා අන්‍යෝන්‍ය ගෞරවය සහිත පරිසරය", "නිරන්තර දඬුවම් දෙන පරිසරය", "සිසුන් අතර අනවශ්‍ය තරගකාරිත්වය", "හුදෙකලා පන්ති කාමර", "යහපත් සමාජ පරිසරය සිසුන්ගේ චිත්තවේගීය වර්ධනයට හා පෞරුෂයට අතිශය හිතකරය."),
        q("සෞඛ්‍ය සම්පන්න පුරවැසියෙකු ලෙස තමන්ගේ සෞඛ්‍යය පිළිබඳව මෙන්ම අන් අයගේ සෞඛ්‍යය පිළිබඳවද සැලකිලිමත් වීමේ සමාජ වගකීම කුමක්ද?", "කැස්ස, කිවිසුම් යාමේදී ලේන්සුවක් භාවිත කිරීම හා පොදු තැන් අපිරිසිදු නොකිරීම", "පොදු ස්ථානවලට කෙළ ගැසීම", "කසළ පාරට දැමීම", "බෝවන රෝග සඟවාගෙන පොදු තැන්වල ගැවසීම", "තම සනීපාරක්ෂක පිළිවෙත් මගින් ප්‍රජාවගේ සෞඛ්‍යය ආරක්ෂා කිරීම උසස් පුරවැසි ගුණයකි."),
        q("පෞද්ගලික සෞඛ්‍යය, නිවැරදි ඉරියව් හා ශරීර සංවර්ධනය අන්‍යෝන්‍ය වශයෙන් බැඳී පවතින බව සනාථ කරන නිවැරදි ප්‍රකාශය කුමක්ද?", "යහපත් සනීපාරක්ෂාව, නිවැරදි ඉරියව් හා සමබල පෝෂණය එක්ව පූර්ණ ශාරීරික හා මානසික යහපැවැත්ම ගොඩනගයි", "ඉරියව් වැදගත් වන්නේ ක්‍රීඩකයන්ට පමණි", "පෞද්ගලික සනීපාරක්ෂාවෙන් ශරීර සංවර්ධනයට කිසිදු බලපෑමක් නැත", "නින්ද සහ සෞඛ්‍යය අතර සම්බන්ධයක් නැත", "සෞඛ්‍යයේ සෑම අංශයක්ම එකිනෙකට බලපාන අතර ඒවායේ එකතුවෙන් පිරිපුන් ජීවිතයක් බිහිවේ.")
    )
}

